// Load Google Charts library
google.charts.load("current", { packages: ["corechart", "line"] });

var currentYear = new Date().getFullYear();

// Function to render charts based on chartType
function renderCharts(chartType) {
    if (chartType === "year") {
        axios
            .get("/chart-data-pendukung")
            .then(function (response) {
                console.log("Response data:", response.data); // Log response data for inspection
                var chartData = response.data;
                google.charts.setOnLoadCallback(function () {
                    drawChartPendukung(chartData);
                });
            })
            .catch(function (error) {
                console.error("Error fetching chart data:", error);
            });
    }
}

// Function to draw chart using Google Charts
function drawChartPendukung(chartData) {
    var data = new google.visualization.DataTable();
    data.addColumn('string', 'Label');
    data.addColumn('number', 'Jumlah Donatur');
    data.addColumn('number', 'Jumlah Sponsor');

    // Check if chartData is valid and has data
    if (chartData.labels && chartData.datasets && chartData.labels.length > 0) {
        // Add data from response to Google Charts data table
        for (var i = 0; i < chartData.labels.length; i++) {
            data.addRow([chartData.labels[i], chartData.datasets[0].data[i], chartData.datasets[1].data[i]]);
        }

        var options = {
            title: chartData.title,
            subtitle: "Tahun " + currentYear,
            width: "100%",
            height: 300,
            legend: { position: "top" },
            pieSliceText: 'value', // Show labels on slices
            chartArea: { left: 50, top: 50, width: "90%", height: 200 },
            series: {
                0: { color: '#1c91c0' }, // Custom color for "Jumlah Donatur"
                1: { color: '#e7711c' }  // Custom color for "Jumlah Sponsor"
            },
            annotations: {
                alwaysOutside: true,
                textStyle: {
                    fontSize: 12,
                    color: '#000',
                    auraColor: 'none'
                }
            }
        };

        var screenWidth = window.innerWidth;

        if (screenWidth > 768) {
            var lineChart = new google.visualization.LineChart(
                document.getElementById("line-chart-pendukung")
            );
            lineChart.draw(data, options);

            document.getElementById("pie-chart-pendukung").style.display = "none";
            document.getElementById("line-chart-pendukung").style.display = "block";
        } else if (screenWidth <= 768 && screenWidth > 500) {
            var pieOptions = {
                title: chartData.title,
                subtitle: "Tahun " + currentYear,
                width: "100%",
                height: 250,
                chartArea: { left: 50, top: 50, width: "90%", height: 150 },
                pieSliceText: 'value', // Hide labels on slices
                tooltip: { trigger: 'selection' }, // Only show tooltip on selection
                pieStartAngle: 90 // Optional: Start angle of the pie chart
            };

            var pieChart = new google.visualization.PieChart(
                document.getElementById("pie-chart-pendukung")
            );
            pieChart.draw(data, pieOptions);

            document.getElementById("line-chart-pendukung").style.display = "none";
            document.getElementById("pie-chart-pendukung").style.display = "block";
        } else if (screenWidth <= 500) {
            var pieOptions = {
                title: chartData.title,
                subtitle: "Tahun " + currentYear,
                width: "100%",
                height: 200,
                chartArea: { left: 50, top: 50, width: "90%", height: 100 },
                pieSliceText: 'value', // Hide labels on slices
                tooltip: { trigger: 'selection' }, // Only show tooltip on selection
                pieStartAngle: 90 // Optional: Start angle of the pie chart
            };

            var pieChart = new google.visualization.PieChart(
                document.getElementById("pie-chart-pendukung")
            );
            pieChart.draw(data, pieOptions);

            document.getElementById("line-chart-pendukung").style.display = "none";
            document.getElementById("pie-chart-pendukung").style.display = "block";
        }
    } else {
        document.getElementById("line-chart-pendukung").style.display = "none";
        document.getElementById("pie-chart-pendukung").style.display = "none";
    }
}



// Function to export chart as JPG, PNG, or PDF
function exportChartPendukung(format) {
    var chartContainer = document.getElementById("chart-container-pendukung");
    chartContainer.classList.add("hide-dropdown");

    html2canvas(chartContainer).then(function (canvas) {
        var imgData;
        var filename = "chart";

        if (format === "jpg") {
            imgData = canvas.toDataURL("image/jpeg");
            filename += ".jpg";
        } else if (format === "png") {
            imgData = canvas.toDataURL("image/png");
            filename += ".png";
        } else if (format === "pdf") {
            const { jsPDF } = window.jspdf; // Ensure jsPDF is correctly loaded
            var pdf = new jsPDF({
                orientation: canvas.width > canvas.height ? 'l' : 'p', // Landscape or Portrait
                unit: 'mm',
                format: [canvas.width * 0.264583, canvas.height * 0.264583] // Convert pixels to mm (1 px = 0.264583 mm)
            });

            var imgWidth = canvas.width * 0.264583; // Width of image in mm
            var imgHeight = canvas.height * 0.264583; // Height of image in mm
            var pageHeight = pdf.internal.pageSize.height; // Page height in mm
            var heightLeft = imgHeight;

            // Add the image to the first page
            pdf.addImage(canvas.toDataURL("image/png"), 'PNG', 0, 0, imgWidth, imgHeight);
            heightLeft -= pageHeight;

            // Add additional pages if needed
            while (heightLeft > 0) {
                pdf.addPage();
                pdf.addImage(canvas.toDataURL("image/png"), 'PNG', 0, -heightLeft, imgWidth, imgHeight);
                heightLeft -= pageHeight;
            }

            filename += ".pdf";
            pdf.save(filename);
            chartContainer.classList.remove("hide-dropdown");
            return;
        } else {
            console.error("Invalid format specified for export.");
            chartContainer.classList.remove("hide-dropdown");
            return;
        }

        var a = document.createElement("a");
        a.href = imgData;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        chartContainer.classList.remove("hide-dropdown");
    });
}


// Callback function to render charts when Google Charts library is loaded
google.charts.setOnLoadCallback(function () {
    renderCharts("year");
});
